frappe.ui.form.on('Jobcard', {
    sales_orders: function (frm) {
        if (frm.doc.sales_orders) {
            frm.clear_table('sales_order_item');
            frappe.model.with_doc('Sales Order', frm.doc.sales_orders, function () {
                let source_doc = frappe.model.get_doc('Sales Order', frm.doc.sales_orders);
                $.each(source_doc.items, function (index, source_row) {
                    const target_row = frm.add_child('sales_order_item');
                    target_row.item_code = source_row.item_code;
                    target_row.rate = source_row.rate;
                    target_row.qty = source_row.qty;
                    target_row.amount = source_row.amount;
                     target_row.delivery_date = source_row.delivery_date;
                    //frm.add_child('sales_order_item').item_code = source_row.item_code; // this table has only one column. You might want to fill more columns.
                    //frm.add_child('sales_order_item').rate = source_row.rate;
                    frm.refresh_field('sales_order_item');
                });
            });
        }
    },
});

